package net.civeira.phylax.features.access.consentpurpose.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.features.access.consentpurpose.domain.valueobject.DescriptionVO;

@RequiredArgsConstructor
public class DescriptionValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<DescriptionVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param description
   * @return
   */
  public T description(DescriptionVO description) {
    this.value = Optional.of(description);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param description
   * @return
   */
  public T description(Optional<DescriptionVO> description) {
    this.value = description;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param description
   * @return
   */
  public T description(String description) {
    this.value = Optional.of(DescriptionVO.from(description));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getDescription() {
    return value.map(DescriptionVO::getDescription);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<DescriptionVO> getDescriptionValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public DescriptionVO readDescription(final Optional<ConsentPurpose> original,
      final ConstraintFailList fails) {
    DescriptionVO result =
        value.orElse(original.map(ConsentPurpose::getDescriptionValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "description", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetDescription() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetDescriptionIfMatches(final String field) {
    if ("description".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
